    end
    function I.read(service,userId)
        local out={valid=false,owned={},roster={},resources={},truncated=false,rejected=0,
            equippedComplete=false,equippedDeclared=0,reason='Client schema unavailable'}
        local session=tableAt(service,'session')
        local profile=tableAt(session,'profile_data')
        local collection=tableAt(tableAt(session,'collection'),'collection_profile_data')
        local owned=tableAt(collection,'owned_units')
        if not session or not owned then return out end
        for _,source in pairs({service,session,profile,collection}) do
            for _,key in ipairs({'user_id','player_id','UserId'}) do
                local id=get(source,key)
                if id~=nil and ((type(id)~='number' and type(id)~='string') or tonumber(id)~=userId) then
                    out.reason='Client owner mismatch/unverified';return out
                end
            end
        end
        out.valid=true;out.reason='Partial local client-service collection'
        local byUUID={}
        local function add(uuid)
            if type(uuid)~='string' then return nil end
            if byUUID[uuid] then return byUUID[uuid] end
            local u=readUnit(uuid,rawget(owned,uuid))
            if u then byUUID[uuid]=u;out.owned[#out.owned+1]=u else out.rejected+=1 end
            return u
        end
        local equipped=tableAt(collection,'equipped_units')
        if equipped then
            out.equippedComplete=true
            local key=nil
            for i=1,32 do
                key=next(equipped,key);if key==nil then break end
                local slot=type(key)=='number' and key or type(key)=='string' and tonumber(key)
                if not C.finite(slot) or slot%1~=0 or slot<1 or slot>8
                    or (type(key)=='string' and key~=tostring(slot)) then out.equippedComplete=false end
                if i==32 and next(equipped,key)~=nil then out.equippedComplete=false end
            end
            for slot=1,8 do
                local numeric=rawget(equipped,slot)
                local named=rawget(equipped,tostring(slot))
                local ambiguous=numeric~=nil and named~=nil and numeric~=named
                local uuid=numeric;if uuid==nil then uuid=named end
                if uuid~=nil then out.equippedDeclared+=1 end
                if ambiguous then out.rejected+=1;out.equippedComplete=false;uuid=nil end
                local u=add(uuid)
                if u then
                    -- A UUID occupying multiple slots is ambiguous, so never
                    -- manufacture a second equipped record for it.
                    if u.slot then out.rejected+=1;out.equippedComplete=false else u.slot=slot;out.roster[#out.roster+1]=u end
                elseif uuid~=nil then out.equippedComplete=false
                end
            end
        end
        local key=nil
        for _=1,400 do
            key=next(owned,key);if key==nil then break end
            add(key)
        end
        if key~=nil and next(owned,key)~=nil then out.truncated=true end
        table.sort(out.owned,function(a,b) return a.id==b.id and a.uuid<b.uuid or a.id<b.id end)
        local items=tableAt(tableAt(session,'inventory'),'inventory_profile_data')
        items=tableAt(items,'normal_items')
        if items then
            for label,aliases in pairs(I.itemAliases) do
                for _,id in ipairs(aliases) do
                    local amount=rawget(items,id)
                    if type(amount)=='table' then amount=number(amount,{'amount','count','quantity'}) end
                    if C.finite(amount) and amount>=0 then out.resources[label]=amount;break end
                end
            end
        end
        local rerolls=number(profile,{'trait_reroll_tokens'})
        if rerolls and rerolls>=0 then out.resources.RerollToken=rerolls end
        return out
    end
    function I.current(binding)
        if type(binding)~='table' then return nil end
        local entry=tableAt(binding.registry,binding.name)
        return tableAt(entry,'module') or entry
    end
    function I.named(roots,names)
        local out={}
        for i=1,math.min(#roots,97) do
            local root=rawget(roots,i)
            local value=type(root)=='table' and rawget(root,'value')
            if type(value)=='table' then
                local parents={value}
                for _,key in ipairs({'CLIENT_SERVICE','CORE_SERVICE','client_services','core_services','services','_services','modules','_modules'}) do
                    local nested=tableAt(value,key);if nested then parents[#parents+1]=nested end
                end
                for _,parent in ipairs(parents) do
                    for j=1,math.min(#names,8) do
                        local name=rawget(names,j)
                        if type(name)=='string' and not out[name] and tableAt(parent,name) then
                            out[name]={registry=parent,name=name,source=tostring(rawget(root,'source') or 'cache')..'.'..name}
                        end
                    end
                end
            end
        end
        return out
    end
    function I.find(roots,userId)
        local seen={}
        local containers={'CLIENT_SERVICE','client_services','services','_services','modules','_modules'}
        for _,serviceName in ipairs({'ItemInventoryServiceClient','StatsServiceClient','GUIService'}) do
            for i=1,math.min(#roots,97) do
                local root=roots[i]
                local value=root and root.value
                if type(value)=='table' then
                    local parents={{value=value,path=root.source}}
                    for _,name in ipairs(containers) do
                        local v=tableAt(value,name)
                        if v then parents[#parents+1]={value=v,path=root.source..'.'..name} end
                    end
                    for _,parent in ipairs(parents) do
                        local entry=tableAt(parent.value,serviceName)
                        local service=tableAt(entry,'module') or entry
                        if service and not seen[service] then
                            seen[service]=true
                            local snapshot=I.read(service,userId)
                            if snapshot.valid then return {service=service,source=parent.path..'.'..serviceName,
                                registry=parent.value,name=serviceName,snapshot=snapshot} end
                        end
                    end
                end
            end
        end
        return nil
    end
    return I
end

end)()

__modules.trial = (function()
-- Explicit single-action Story tests. No route claim, replay or emitted tick actions.
return function(C,cfg,log)
    local T={state='IDLE',reason='No supervised action attempted',pending=nil,placements=0,upgrades=0,
        attemptRun=nil,attempted={}}
    function T:quote(kind,s,p)
        if s.externalControllerActive then return nil,'Close Zeno before using a native action test' end
        if kind~='place' and kind~='upgrade' then return nil,'Unsupported test action' end
        if self.pending or s.transportBlocked then return nil,'A request/test is still pending' end
        if s.mutationFence then return nil,'Prior mutation lacks exact feedback; enter a fresh match' end
        if self.state=='UNCONFIRMED' and self.attemptRun==s.run then
            return nil,'Previous test unconfirmed; inspect the report and enter a fresh match'
        end
        if self.attemptRun==s.run and self.attempted[kind] then
            return nil,'One '..kind..' test already attempted this run; inspect the report'
        end
        if not s.inMatch or not s.stageVerified or not s.modeVerified or s.mode~='Story' then
            return nil,'An observed free Story match is required'
        end
        if not s.started or s.resultVisible then return nil,'Start waves in an unfinished match first' end
        if s.unitsComplete~=true then return nil,'Tower observation incomplete' end
        if not C.finite(s.now) or not C.finite(s.rosterAt) or s.now-s.rosterAt<0 or s.now-s.rosterAt>15 then
            return nil,'Fresh equipped records unavailable'
        end
        if type(p)~='table' or type(p.entries)~='table' or #p.entries~=1 or p.source~='user-recorded' then
            return nil,'Record exactly one own tower first'
        end
        if not C.contextMatches(p,s) then return nil,'Recorded stage/mode/place differs' end
        if p.costScale~=nil and (not C.finite(s.costScale) or p.costScale~=s.costScale) then
            return nil,'Cost modifier changed or became unknown; record again'
        end
        local e=p.entries[1]
        if type(e)~='table' or type(e.uuid)~='string' or e.uuid=='' or type(e.id)~='string' or e.id==''
            or C.distance(e.pos,e.pos)~=0 or not C.finite(e.cost) or e.cost<=0 then
            return nil,'Recorded position or deployment price invalid'
        end
        local equipped
        for _,u in ipairs(s.roster or {}) do if u.uuid==e.uuid and u.id==e.id then equipped=u;break end end
        if not equipped then return nil,'Recorded unit is no longer equipped' end
        if p.testSlot~=nil and (p.testSlot~=cfg.trialSlot or equipped.slot~=p.testSlot) then
            return nil,'Selected test slot changed; record its current tower again'
        end
        if C.finite(equipped.cost) and equipped.cost~=e.cost then return nil,'Deployment price changed; record again' end
        local q={kind=kind,uuid=e.uuid,id=e.id,pos={e.pos[1],e.pos[2],e.pos[3]},cost=e.cost,
            slot=equipped.slot,run=s.run,stage=s.stage,mode=s.mode,placeId=s.placeId,at=s.now}
        if kind=='place' then
            for _,u in ipairs(s.units or {}) do
                if u.uuid==e.uuid and u.id==e.id then
                    return nil,'Target already placed; save its test profile, then use a fresh copy of this stage'
                end
                if C.distance(u.pos,e.pos)<=3 then return nil,'Another tower occupies the recorded position' end
            end
        else
            local found
            for _,u in ipairs(s.units or {}) do
                if u.uuid==e.uuid and u.id==e.id and C.distance(u.pos,e.pos)<=3 then
                    if found then return nil,'Recorded upgrade target is ambiguous' end
                    found=u
                end
            end
            if not found or not found.key then return nil,'Recorded tower is not present' end
            if not C.finite(found.level) or found.level<0 or found.level%1~=0
                or not C.finite(found.nextCost) or found.nextCost<=0 then
                return nil,'Current upgrade level or next price unknown'
            end
            q.key=found.key;q.level=found.level;q.cost=found.nextCost
        end
        local reserve=C.finite(cfg.reserve) and math.max(0,cfg.reserve) or 0
        if not C.finite(s.cash) or s.cash-reserve<q.cost then
            return nil,'Need '..q.cost..' match Yen + '..reserve..' reserve; have '..tostring(s.cash or '?')
        end
        return q
    end
    function T:begin(kind,s,p,displayed)
        local q,why=self:quote(kind,s,p)
        if not q then return nil,why end
        if type(displayed)~='table' or not C.finite(displayed.at) or s.now-displayed.at<0 or s.now-displayed.at>5
            or displayed.kind~=q.kind or displayed.uuid~=q.uuid or displayed.id~=q.id or displayed.cost~=q.cost
            or displayed.run~=q.run or not C.contextMatches(displayed,s) or displayed.key~=q.key
            or displayed.slot~=q.slot or displayed.level~=q.level or C.distance(displayed.pos,q.pos)>0.01 then
            return nil,'Displayed price/target changed or expired; review the refreshed button'
        end
        if self.attemptRun~=s.run then self.attemptRun=s.run;self.attempted={} end
        self.attempted[kind]=true
        q.before={};for _,u in ipairs(s.units or {}) do if u.key then q.before[u.key]=true end end
        q.cashBefore=s.cash
        self.pending=q;self.state='WAITING';self.reason='One '..kind..' request; awaiting exact tower readback'
        self.last={kind=kind,id=q.id,cost=q.cost,cashBefore=s.cash}
        log:add('TRIAL ATTEMPT',kind..' '..q.id..' | quoted match Yen='..q.cost..'; no automatic retry')
        return {kind=kind,uuid=q.uuid,id=q.id,pos=table.clone(q.pos),key=q.key}
    end
    local function finish(self,state,reason,s)
        self.pending=nil;self.state=state;self.reason=reason
        if self.last and s then self.last.cashAfter=s.cash end
        log:add('TRIAL '..state,reason)
    end
    function T:cancel(reason)
        if self.pending then finish(self,'UNCONFIRMED',reason or 'Test cancelled; result unconfirmed') end
    end
    function T:tick(s)
        local q=self.pending;if not q then return nil end
        if not C.finite(s.now) or s.now-q.at>8 or s.now<q.at then
            finish(self,'UNCONFIRMED','Feedback deadline exceeded; no automatic retry',s);return nil
        end
        if s.run~=q.run or not s.inMatch or not s.stageVerified or not s.modeVerified or s.mode~='Story'
            or not C.contextMatches(q,s)
            or s.unitsComplete~=true or s.resultVisible then
            finish(self,'UNCONFIRMED','Match/observation changed before confirmation',s);return nil
        end
        if q.kind=='place' then
            local match,ambiguous=C.placementVerified(q,s.units)
            if ambiguous then finish(self,'UNCONFIRMED','Multiple matching new towers; placement is ambiguous',s)
            elseif match then
                self.placements+=1
                finish(self,'OBSERVED','New exact '..q.id..' tower observed at the recorded position after request',s)
            end
        else
            for _,u in ipairs(s.units or {}) do
                if u.key==q.key and u.uuid==q.uuid and u.id==q.id and C.distance(u.pos,q.pos)<=3
                    and C.finite(u.level) and u.level>q.level then
                    if u.level==q.level+1 then
                        self.upgrades+=1
                        finish(self,'OBSERVED','Exact '..q.id..' tower upgrade '..q.level..' → '..u.level..' observed',s)
                    else finish(self,'UNCONFIRMED','Unexpected upgrade jump; result unconfirmed',s) end
                    break
                end
            end
        end
        return nil -- this observer never starts a second action
    end
    function T:text()
        local out='Single-action test: '..self.state..' | '..self.reason..
            '\nObserved trial placements='..self.placements..' | upgrades='..self.upgrades
        if self.last then
            out=out..'\nLast test='..self.last.kind..' '..self.last.id..' | quoted match Yen='..self.last.cost..
                ' | cash before='..tostring(self.last.cashBefore)..' after='..tostring(self.last.cashAfter or '?')..
                ' (balance changes are not attributed costs)'
        end
        return out
    end
    return T
end

end)()

__modules.team = (function()
-- Pure recorded-team orchestration. No Rukia-route claims or native calls.
return function(C,cfg,log)
    local T={armed=false,state='IDLE',reason='Team Auto OFF',pending=nil,
        placements=0,upgrades=0,wins=0,losses=0,runs=0,reportDue=false}
    local function role(e)
        return table.find({'combat','farm','buff'},e.role) and e.role or 'unknown'
    end
    local function matches(s,p)
        local out,used={},{}
        for i,e in ipairs(p.entries) do
            local found
            for _,u in ipairs(s.units or {}) do
                if u.key and u.uuid==e.uuid and u.id==e.id and C.distance(u.pos,e.pos)<=3 then
                    if found and found.key~=u.key then return nil,'Multiple towers match recorded target '..i end
                    found=u
                end
            end
            if found then
                if used[found.key] then return nil,'One tower matches multiple recorded targets' end
                used[found.key]=true;out[i]=found
            end
        end
        return out
    end
    function T:coverage(s,p)
        local count,total,missing=0,0,{}
        for _,u in ipairs(s.roster or {}) do
            total+=1;local found=false
            for i,e in ipairs(type(p)=='table' and type(p.entries)=='table' and p.entries or {}) do
                if i>24 then break end
                if type(e)=='table' and e.uuid==u.uuid and e.id==u.id then found=true;break end
            end
            if found then count+=1 else missing[#missing+1]='slot '..tostring(u.slot)..' '..u.id end
        end
        return count,total,missing
    end
    function T:readiness(s,p)
        local b=C.profileReadiness(s,p,cfg)
        if not s.modeVerified or s.mode~='Story' then b[#b+1]='Team Auto currently supports observed Story only' end
        if type(p)~='table' or p.kind~='team-v1' then b[#b+1]='Record a team profile first' end
        local covered,total,missing=self:coverage(s,p)
        if s.rosterComplete~=true then b[#b+1]='Declared equipped-slot data is incomplete or ambiguous' end
        if total==0 or covered~=total then b[#b+1]='Record every equipped slot: '..table.concat(missing,', ') end
        for _,u in ipairs(s.roster or {}) do
            if not C.finite(u.cost) or u.cost<=0 then b[#b+1]='Current deployment price unknown: '..u.id end
        end
        for _,u in ipairs(s.units or {}) do
            if type(p)=='table' and type(p.entries)=='table' then
                for _,e in ipairs(p.entries) do
                    if type(e)=='table' and u.uuid==e.uuid and u.id==e.id and C.distance(u.pos,u.pos)~=0 then
                        b[#b+1]='Live recorded tower position unavailable';break
                    end
                end
            end
        end
        if not C.finite(cfg.reserve) or cfg.reserve<0 or not C.finite(cfg.maxSeconds) or cfg.maxSeconds<30
            or not C.finite(cfg.maxRuns) or cfg.maxRuns<1 then b[#b+1]='Invalid session budget/limits' end
        if type(p)=='table' and type(p.entries)=='table' then
            for i,e in ipairs(p.entries) do
                if i>24 then break end
                if type(e)=='table' then
                    for j=1,i-1 do
                        local other=p.entries[j]
                        if type(other)=='table' and other.uuid==e.uuid and other.id==e.id and C.distance(other.pos,e.pos)<=3 then
                            b[#b+1]='Recorded copies too close for unique readback';break
                        end
                    end
                end
            end
            if #b==0 then local _,why=matches(s,p);if why then b[#b+1]=why end end
        end
        return b
    end
    function T:stop(reason,state)
        if self.pending then self.uncertainRun=self.run end
        local active=self.armed or self.pending~=nil
        self.armed=false;self.pending=nil;self.state=state or 'BLOCKED';self.reason=reason
        if active then self.reportDue=true end
        log:add('TEAM '..self.state,reason)
    end
    function T:reject(reason) self:stop('Request rejected/unconfirmed: '..tostring(reason)) end
    function T:arm(s,p)
        if self.uncertainRun==s.run then self:stop('Prior action unconfirmed; enter a fresh match');return false end
        local b=self:readiness(s,p)
        if #b>0 then self:stop(table.concat(b,'; '));return false end
        self.armed=true;self.state='RUNNING';self.reason='Supervised recorded Story team'
        self.run=s.run;self.startedAt=s.now;self.progressAt=s.now;self.lastWave=s.wave
        self.lastAction=-math.huge;self.pending=nil;self.countedRun=nil;self.runs=0;self.dataWaitAt=nil;self.reportDue=false
        log:add('TEAM ARM','Recorded Story team; no premium actions');return true
    end
    function T:tick(s,p)
        if not self.armed then return nil end
        if s.now-self.startedAt>=cfg.maxSeconds then self:stop('Team session time limit');return nil end
        if self.pending and self.pending.kind=='replay' then
            if s.now-self.pending.at>15 then self:stop('Replay reset/identity timeout');return nil end
            if s.run==self.run then return nil end
            if self.pending.roundToken and self.pending.roundToken==s.roundToken then return nil end
            if not s.inMatch or not s.stageVerified then return nil end
            if not C.contextMatches(p,s) or not s.modeVerified or s.mode~='Story' then self:stop('Replay changed stage/mode');return nil end
            if s.resultVisible then return nil end
            -- A fresh round must clear the recorded towers before new spending.
            for _,u in ipairs(s.units or {}) do
                for _,e in ipairs(p.entries) do if u.uuid==e.uuid and u.id==e.id then return nil end end
            end
            self.pending=nil;self.run=s.run;self.countedRun=nil;self.lastWave=s.wave;self.progressAt=s.now
            self.lastAction=-math.huge;self.state='RUNNING';self.dataWaitAt=nil
        elseif s.run~=self.run then self:stop('Match changed; recheck team before arming');return nil end
        if not s.inMatch or not s.stageVerified or not s.modeVerified or s.mode~='Story' or s.unitsComplete~=true then
            self:stop('Match/observation became unsupported');return nil
        end
        if s.wave~=self.lastWave then self.lastWave=s.wave;self.progressAt=s.now end
        if s.resultVisible then
            if self.countedRun~=s.run then
                self.countedRun=s.run;self.runs+=1
                if s.outcome=='Victory' then self.wins+=1 elseif s.outcome=='Defeat' then self.losses+=1 end
                log:add('TEAM RESULT',tostring(s.outcome)..' | source='..tostring(s.outcomeSource or 'UI'))
            end
            if self.pending then self:stop('Match ended during an unresolved action; replay stopped','RESULT');return nil end
            if s.outcome~='Victory' or not cfg.replay or not cfg.replayFreeConfirmed
                or not C.contextMatches(cfg.replayContext,s) or self.runs>=cfg.maxRuns then
                self:stop('Result: '..tostring(s.outcome)..'; replay stopped','RESULT');return nil
            end
            if s.transportBlocked then return nil end
            self.pending={kind='replay',at=s.now,roundToken=s.roundToken};self.state='REPLAY_WAIT';self.reason='Waiting for a fresh matching round'
            return {kind='replay'}
        end
        if self.pending then
            local q=self.pending
            if s.now-q.at>8 then self:stop(q.kind..' feedback timeout; no retry');return nil end
            local found,ambiguous
            if q.kind=='place' then found,ambiguous=C.placementVerified(q,s.units)
            else
                for _,u in ipairs(s.units) do
                    if u.key==q.key and u.uuid==q.uuid and u.id==q.id and C.distance(u.pos,q.pos)<=3 and C.finite(u.level) and u.level>q.level then
                        if u.level~=q.level+1 then self:stop('Unexpected upgrade jump');return nil end
                        found=u;break
                    end
                end
            end
            if ambiguous then self:stop('Ambiguous placement readback');return nil end
            if found then
                if q.kind=='place' then self.placements+=1 else self.upgrades+=1 end
                log:add('TEAM CONFIRMED',q.kind..' '..q.id)
                self.pending=nil;self.lastAction=s.now;self.progressAt=s.now;self.state='RUNNING'
            end
            return nil
        end
        local b=self:readiness(s,p)
        if #b>0 then self:stop(table.concat(b,'; '));return nil end
        if s.now-self.progressAt>180 then self:stop('No wave/action progress for 180 seconds');return nil end
        if not s.started or s.transportBlocked or s.now-self.lastAction<1.5 then return nil end
        local matched,why=matches(s,p)
        if not matched then self:stop(why);return nil end
        local missing,combatExists,farmExists,hasCombat={},false,false,false
        for i,e in ipairs(p.entries) do
            if role(e)=='combat' then hasCombat=true end
            if matched[i] then
                if role(e)=='combat' then combatExists=true elseif role(e)=='farm' then farmExists=true end
            else missing[#missing+1]={entry=e,index=i} end
        end
        if #missing>0 then
            local options={}
            for _,v in ipairs(missing) do
                local e=v.entry
                local allowed=not hasCombat or combatExists or role(e)=='combat' or (not farmExists and role(e)=='farm')
                if allowed and (e.wave or 0)<=s.wave and s.cash-cfg.reserve>=e.cost then options[#options+1]=v end
            end
            table.sort(options,function(a,b)
                local rank={combat=1,farm=2,buff=3,unknown=4}
                if combatExists then rank={farm=1,combat=2,buff=3,unknown=4} end
                local ra,rb=rank[role(a.entry)],rank[role(b.entry)]
                if ra~=rb then return ra<rb end
                if a.entry.cost~=b.entry.cost then return a.entry.cost<b.entry.cost end
                return a.index<b.index
            end)
            local chosen=options[1]
            if not chosen then
                self.state='WAITING';self.reason=not combatExists and farmExists and hasCombat and 'Saving for the first combat unit' or 'Waiting for an affordable recorded placement'
                return nil
            end
            local e=chosen.entry;local before={}
            for _,u in ipairs(s.units) do if u.key then before[u.key]=true end end
            self.pending={kind='place',uuid=e.uuid,id=e.id,pos=table.clone(e.pos),before=before,at=s.now}
            self.state='PLACE_WAIT';self.reason='Placing '..e.id..' | quoted Yen='..e.cost
            return {kind='place',uuid=e.uuid,id=e.id,pos=table.clone(e.pos)}
        end
        if not cfg.upgrade then self.state='HOLDING';self.reason='Recorded team placed; upgrades disabled';return nil end
        local best,bestIndex,unknown=nil,nil,false
        for i,u in pairs(matched) do
            local maximum=C.finite(u.maxLevel) and C.finite(u.level) and u.level>=u.maxLevel
            if not maximum then
                if not C.finite(u.level) or u.level<0 or u.level%1~=0 or not C.finite(u.nextCost) or u.nextCost<=0 then unknown=true
                elseif s.cash-cfg.reserve>=u.nextCost and (not best or u.level<best.level
                    or (u.level==best.level and (u.nextCost<best.nextCost or (u.nextCost==best.nextCost and i<bestIndex)))) then
                    best=u;bestIndex=i
                end
            end
        end
        if best then
            self.dataWaitAt=nil
            self.pending={kind='upgrade',uuid=best.uuid,id=best.id,key=best.key,pos=table.clone(best.pos),level=best.level,at=s.now}
            self.state='UPGRADE_WAIT';self.reason='Upgrading '..best.id..' | quoted Yen='..best.nextCost
            return {kind='upgrade',key=best.key,uuid=best.uuid,id=best.id}
        end
        if unknown then
            self.dataWaitAt=self.dataWaitAt or s.now
            self.reason='Waiting for known upgrade levels/prices'
            if s.now-self.dataWaitAt>15 then self:stop('Upgrade level/price unavailable; not treated as maximum') end
        else self.dataWaitAt=nil;self.reason='Recorded team placed; waiting for funds or the observed result' end
        if self.armed then self.state='HOLDING' end
        return nil
    end
    function T:text(s,p)
        local count,total,missing=self:coverage(s or {},p)
        return 'TEAM AUTO: '..self.state..' | '..self.reason..'\nRecorded slots '..count..' / '..total..
            ' | targets='..tostring(type(p)=='table' and type(p.entries)=='table' and #p.entries or 0)..
            (#missing>0 and '\nMissing: '..table.concat(missing,', ') or '')..
            '\nTeam-confirmed placements='..self.placements..' upgrades='..self.upgrades..
            ' | wins='..self.wins..' losses='..self.losses
    end
    return T
end

end)()

__modules.autoplay = (function()
-- Native automatic combat policy. Pure snapshots in; at most one request out.
-- Geometry and transport belong to their adapters. RPC replies are never proof.
return function(C,cfg,log)
    log=log or C.logger()
    local A={armed=false,state='IDLE',reason='Native Auto OFF',pending=nil,
        placements=0,upgrades=0,confirmations=0,runs=0,wins=0,losses=0,reportDue=false,
        targetStatus='Game default target priority'}
    local function cap(u)
        if not C.finite(u.spawnCap) or u.spawnCap<1 or u.spawnCap%1~=0 then return nil end
        return C.hasTrait(u,'Unique') and 1 or math.min(24,u.spawnCap)
    end
    local function acquired(s)
        if cfg.goal~='Acquire' or not C.finite(s.now) or not C.finite(s.ownedAt)
            or s.now<s.ownedAt or s.now-s.ownedAt>15 or type(s.owned)~='table' then return false end
        for _,u in ipairs(s.owned) do
            if type(u)=='table' and C.isRukia(u.id) and u.statScope=='collection'
                and type(u.uuid)=='string' and u.uuid~='' then return true end
        end
        return false
    end
    local function counts(s)
        local out={};for _,u in ipairs(s.roster or {}) do out[u.uuid]=0 end
        for _,v in ipairs(s.units or {}) do
            for _,u in ipairs(s.roster or {}) do
                if v.uuid==u.uuid and v.id==u.id then out[u.uuid]+=1;break end
            end
        end
        return out
    end
    local function spot(s,u)
        local list=type(s.autoSpots)=='table' and s.autoSpots[u.uuid]
        if type(list)~='table' then return nil end
        for i,e in ipairs(list) do
            if i>24 then break end
            local p=type(e)=='table' and e.pos
            if C.distance(p,p)==0 then
                local free=true
                for _,v in ipairs(s.units or {}) do if C.distance(v.pos,p)<=3 then free=false;break end end
                if free then return {p[1],p[2],p[3]} end
            end
        end
        return nil
    end
    function A:readiness(s,pending)
        if type(s)~='table' or type(s.roster)~='table' or type(s.units)~='table' then
            return {'Native snapshot/roster/tower schema unsupported'}
        end
        for _,u in ipairs(s.roster) do
            if type(u)~='table' or type(u.uuid)~='string' or u.uuid=='' or type(u.id)~='string' or u.id=='' then
                return {'Equipped UUID/ID schema unsupported'}
            end
        end
        for _,u in ipairs(s.units) do if type(u)~='table' then return {'Tower snapshot schema unsupported'} end end
        local b={}
        local function need(ok,why) if not ok then b[#b+1]=why end end
        need(s.run~=nil and s.roundToken~=nil,'Observed native round identity unavailable')
        need(s.inMatch==true and s.stageVerified==true,'Observed match/stage unavailable')
        need(s.modeVerified==true and table.find({'Story','Dungeon','Infinite','Challenge','Raid','Legend','Portal'},s.mode)~=nil,
            'Native Auto requires an observed supported mode; Events remain unavailable')
        need(s.externalControllerActive~=true,'External controller active; native mutation blocked')
        need(s.unitsComplete==true,'Own tower observation incomplete')
        need(s.rosterComplete==true,'Every equipped slot must be observed')
        need(C.finite(s.now) and C.finite(s.rosterAt) and s.now>=s.rosterAt and s.now-s.rosterAt<=15,'Fresh equipped UUIDs unavailable')
        need(C.finite(s.cash) and s.cash>=0,'Live match Yen unknown')
        need(C.finite(cfg.reserve) and cfg.reserve>=0 and C.finite(cfg.maxSeconds) and cfg.maxSeconds>=30,'Invalid session budget/limits')
        need(type(s.roster)=='table' and #s.roster>0 and #s.roster<=6,'Equipped roster must contain1–6 slots')
        need(type(s.units)=='table' and #s.units<=24,'Own tower target limit exceeds24')
        if not pending then
            need(s.transportBlocked~=true,'Native transport still outstanding')
            need(s.mutationFence~=true,'Previous mutation lacks exact feedback; enter a fresh round')
        end
        local seen,keys={},{}
        local current=counts(s)
        for _,u in ipairs(s.roster or {}) do
            local identity=type(u.uuid)=='string' and u.uuid~='' and type(u.id)=='string' and u.id~=''
            need(identity and not seen[u.uuid],'Equipped UUID/ID missing or duplicated')
            if identity then seen[u.uuid]=true end
            local limit=cap(u)
            need(limit~=nil,'Known positive integer spawn cap required: '..tostring(u.id))
            need(C.finite(u.cost) and u.cost>0,'Deployment price unknown: '..tostring(u.id))
            if limit and identity then
                need(current[u.uuid]<=limit,'Observed copies exceed equipped cap: '..u.id)
                if not pending and #(s.units or {})<24 and current[u.uuid]<limit then
                    need(spot(s,u)~=nil,'Observed placement spot unavailable: slot '..tostring(u.slot)..' '..u.id)
                end
            end
        end
        for _,u in ipairs(s.units or {}) do
            need(u.key~=nil and not keys[u.key] and C.distance(u.pos,u.pos)==0,'Tower key/position missing or ambiguous')
            if u.key then keys[u.key]=true end
        end
        return b
    end
    function A:stop(reason,state)
        if self.pending then self.uncertainRun=self.run;self.uncertainRound=self.roundToken end
        self.reportDue=self.armed or self.pending~=nil or self.reportDue
        self.armed=false;self.pending=nil;self.reason=tostring(reason);self.state=state or 'BLOCKED'
        log:add('AUTO '..self.state,self.reason)
    end
    function A:reject(reason) self:stop('Request rejected/unconfirmed: '..tostring(reason)) end
    function A:arm(s)
        if type(s)~='table' then self:stop('Native snapshot unavailable');return false end
        if self.pending then self:stop('Pending action cannot be rearmed');return false end
        if self.uncertainRun==s.run or (self.uncertainRound~=nil and self.uncertainRound==s.roundToken) then
            self:stop('Prior action unconfirmed; enter a fresh round');return false
        end
        local b=self:readiness(s,false)
        if #b>0 then self:stop(table.concat(b,'; '));return false end
        if s.resultVisible or s.defeated or s.dead then self:stop('Match already ended');return false end
        self.armed=true;self.state='RUNNING';self.reason='Experimental native combat'
        self.run=s.run;self.roundToken=s.roundToken;self.stage=s.stage;self.mode=s.mode;self.placeId=s.placeId
        self.startedAt=s.now;self.progressAt=s.now;self.lastWave=s.wave;self.lastAction=-math.huge
        self.cursor=1;self.dataWaitAt=nil;self.reportDue=false
        self.targetStatus=cfg.autoTarget=='first' and 'First priority awaits completed placements' or 'Game default target priority'
        log:add('AUTO ARM','Observed '..s.mode..'; bounded equipped targets')
        return true
    end
    function A:tick(s)
        if not self.armed then return nil end
        if type(s)~='table' then self:stop('Native snapshot unavailable');return nil end
        if acquired(s) then self:stop('Exact collection Rukia acquired','GOAL_MET');return nil end
        if not C.finite(s.now) or s.now<self.startedAt or s.now-self.startedAt>=cfg.maxSeconds then
            self:stop('Native session time limit or invalid clock');return nil
        end
        if s.run~=self.run or s.roundToken~=self.roundToken or s.stage~=self.stage or s.mode~=self.mode or s.placeId~=self.placeId then
            self:stop('Unexpected match/stage/native round change; arm verified round explicitly');return nil
        end
        if s.resultVisible or s.defeated or s.dead then
            self.runs+=1
            if s.outcome=='Victory' then self.wins+=1 elseif s.outcome=='Defeat' or s.defeated then self.losses+=1 end
            self:stop('Observed result: '..tostring(s.outcome or 'ended'),'RESULT');return nil
        end
        local b=self:readiness(s,self.pending~=nil)
        if #b>0 then self:stop(table.concat(b,'; '));return nil end
        if s.wave~=self.lastWave then self.progressAt=s.now;self.lastWave=s.wave end
        if self.pending then
            local p=self.pending
            if s.now-p.at>8 then self:stop(p.kind..' feedback timeout; no blind retry');return nil end
            local found,ambiguous
            if p.kind=='place' then found,ambiguous=C.placementVerified(p,s.units)
            elseif p.kind=='priority' then
                for _,u in ipairs(s.units) do
                    if u.key==p.key and u.uuid==p.uuid and u.id==p.id and C.distance(u.pos,p.pos)<=3
                        and type(u.priority)=='string' and u.priority==p.target then found=u;break end
                end
            else
                for _,u in ipairs(s.units) do
                    if u.key==p.key and u.uuid==p.uuid and u.id==p.id and C.distance(u.pos,p.pos)<=3
                        and C.finite(u.level) and u.level>p.level then
                        if u.level~=p.level+1 then self:stop('Unexpected upgrade level jump');return nil end
                        found=u;break
                    end
                end
            end
            if ambiguous then self:stop('Ambiguous placement feedback');return nil end
            if found then
                if p.kind=='place' then self.placements+=1;self.cursor=p.slotIndex%#s.roster+1
                elseif p.kind=='priority' then self.confirmations+=1
                else self.upgrades+=1 end
                self.pending=nil;self.lastAction=s.now;self.progressAt=s.now;self.state='RUNNING'
                log:add('AUTO CONFIRMED',p.kind..' '..p.id)
            end
            return nil
        end
        if s.now-self.progressAt>180 then self:stop('No wave/action progress for180 seconds');return nil end
        if not s.started or s.now-self.lastAction<1.5 then return nil end
        local current=counts(s);local hasCombat,combat,farm=false,false,false
        for _,u in ipairs(s.roster) do
            if u.role=='combat' or u.role=='unknown' or u.role==nil then hasCombat=true;if current[u.uuid]>0 then combat=true end end
            if u.role=='farm' and current[u.uuid]>0 then farm=true end
        end
        local options,missing={},false
        if #s.units<24 then
            for i,u in ipairs(s.roster) do
                if current[u.uuid]<cap(u) then
                    missing=true
                    local attack=u.role=='combat' or u.role=='unknown' or u.role==nil
                    local allowed=not hasCombat or combat or attack or (u.role=='farm' and not farm)
                    if allowed and s.cash-cfg.reserve>=u.cost then options[#options+1]={u=u,index=i,attack=attack} end
                end
            end
        end
        if missing then
            table.sort(options,function(a,b)
                if hasCombat and not combat and a.attack~=b.attack then return a.attack end
                local ac,bc=current[a.u.uuid],current[b.u.uuid]
                if (ac==0)~=(bc==0) then return ac==0 end
                if cfg.autoMethod=='Cheapest' and a.u.cost~=b.u.cost then return a.u.cost<b.u.cost end
                local da=(a.index-self.cursor)%#s.roster;local db=(b.index-self.cursor)%#s.roster
                return da<db
            end)
            local choice=options[1]
            if not choice then
                self.state='WAITING';self.reason=hasCombat and not combat and farm and 'Saving for first combat unit' or 'Waiting for affordable placement';return nil
            end
            local u=choice.u;local pos=spot(s,u)
            if not pos then self:stop('Observed placement spot unavailable: slot '..tostring(u.slot)..' '..u.id);return nil end
            local before={};for _,v in ipairs(s.units) do before[v.key]=true end
            self.pending={kind='place',uuid=u.uuid,id=u.id,pos=pos,before=before,at=s.now,slotIndex=choice.index}
            self.state='PLACE_WAIT';self.reason='Placing '..u.id..' | quoted Yen='..u.cost
            return {kind='place',uuid=u.uuid,id=u.id,pos=table.clone(pos)}
        end
        self.state='HOLDING'
        if cfg.autoTarget=='first' then
            local candidate,unavailable=nil,{}
            for _,u in ipairs(s.units) do
                local entry
                for _,v in ipairs(s.roster) do if v.uuid==u.uuid and v.id==u.id then entry=v;break end end
                if entry and entry.role~='farm' and entry.role~='buff' then
                    if type(u.priority)~='string' or u.priority=='' then unavailable[#unavailable+1]=u.id
                    elseif u.priority~='first' and not candidate then candidate=u end
                end
            end
            self.targetStatus=#unavailable>0 and 'Target priority unavailable: '..table.concat(unavailable,', ')
                or 'First priority observed on supported combat towers'
            if candidate then
                self.pending={kind='priority',key=candidate.key,uuid=candidate.uuid,id=candidate.id,
                    pos=table.clone(candidate.pos),target='first',at=s.now}
                self.state='PRIORITY_WAIT';self.reason='Requesting observed combat target priority: first'
                return {kind='priority',key=candidate.key,uuid=candidate.uuid,id=candidate.id,target='first'}
            end
        else self.targetStatus='Game default target priority' end
        if not cfg.upgrade then self.reason='Known caps/target limit reached; upgrades disabled';return nil end
        local best,unknown=nil,false
        for _,u in ipairs(s.units) do
            local equipped=false
            for _,v in ipairs(s.roster) do if v.uuid==u.uuid and v.id==u.id then equipped=true;break end end
            if equipped then
                local levelKnown=C.finite(u.level) and u.level>=0 and u.level%1==0
                local maximum=levelKnown and C.finite(u.maxLevel) and u.maxLevel>=0 and u.maxLevel%1==0 and u.level>=u.maxLevel
                if not maximum then
                    if not levelKnown or not C.finite(u.nextCost) or u.nextCost<=0 then unknown=true
                    elseif s.cash-cfg.reserve>=u.nextCost then
                        local cheap=cfg.autoUpgradeMethod=='Cheapest'
                        local better=not best or (cheap and (u.nextCost<best.nextCost or (u.nextCost==best.nextCost and u.level<best.level)))
                            or (not cheap and (u.level<best.level or (u.level==best.level and u.nextCost<best.nextCost)))
                        if better then best=u end
                    end
                end
            end
        end
        if best then
            self.dataWaitAt=nil
            self.pending={kind='upgrade',uuid=best.uuid,id=best.id,key=best.key,pos=table.clone(best.pos),level=best.level,at=s.now}
            self.state='UPGRADE_WAIT';self.reason='Upgrading '..best.id..' | quoted Yen='..best.nextCost
            return {kind='upgrade',key=best.key,uuid=best.uuid,id=best.id}
        end
        if unknown then
            self.dataWaitAt=self.dataWaitAt or s.now;self.reason='Waiting for known upgrade level/price; maximum unproven'
            if s.now-self.dataWaitAt>15 then self:stop('Upgrade level/price unavailable; maximum unproven') end
        else self.dataWaitAt=nil;self.reason='Known targets placed; waiting for funds or result' end
        return nil
    end
    function A:text(_s)
        return 'NATIVE AUTO: '..self.state..' | '..self.reason..'\nConfirmed placements='..self.placements..
            ' upgrades='..self.upgrades..' priority='..self.confirmations..' | wins='..self.wins..' losses='..self.losses..
            '\n'..self.targetStatus
    end
    return A
end

end)()

__modules.navigation = (function()
-- Read-only, bounded placement proposals from the currently loaded native map.
-- No map coordinates, cloned models, global scans, or server calls live here.
return function(C,WS,RS,log)
    local N={closed=false,planning=false}
    local function child(parent,name) return parent and parent:FindFirstChild(name) end
    local function position(p)
        return p and C.finite(p.X) and C.finite(p.Y) and C.finite(p.Z) and {p.X,p.Y,p.Z} or nil
    end
    local function children(parent,limit,label)
        if not parent then return nil,label..' unavailable' end
        local list=parent:GetChildren()
        if type(list)~='table' or #list>limit then return nil,label..' observation exceeds bounded limit' end
        return list
    end
    local function lanePoint(percent)
        local bases=child(WS,'_BASES');local pve=child(bases,'pve');local root=child(pve,'LANES')
        local lanes,why=children(root,8,'_BASES.pve.LANES')
        if not lanes then return nil,why end
        if #lanes==0 then return nil,'Native LANES empty' end
        table.sort(lanes,function(a,b) return tostring(a.Name)<tostring(b.Name) end)
        local longest,length=nil,0
        for _,lane in ipairs(lanes) do
            local nodes;nodes,why=children(lane,96,'Native lane nodes')
            if not nodes then return nil,why end
            local first,last,numbered,seen=nil,nil,{},{}
            for _,node in ipairs(nodes) do
                local name=node.Name;local index=tonumber(name)
                if name=='spawn' or name=='final' or index then
                    if not node:IsA('BasePart') then return nil,'Native lane endpoint/node is not a BasePart' end
                    local pos=position(node.Position)
                    if not pos then return nil,'Native lane position invalid' end
                    if name=='spawn' then
                        if first then return nil,'Duplicate native spawn node' end;first=pos
                    elseif name=='final' then
                        if last then return nil,'Duplicate native final node' end;last=pos
                    else
                        if not C.finite(index) or index<1 or index%1~=0 or seen[index] then return nil,'Duplicate/invalid numeric native lane node' end
                        seen[index]=true;numbered[#numbered+1]={index=index,pos=pos}
                    end
                end
            end
            if not first or not last then return nil,'Native lane requires observed spawn and final parts' end
            table.sort(numbered,function(a,b) return a.index<b.index end)
            local points={first};for _,v in ipairs(numbered) do points[#points+1]=v.pos end;points[#points+1]=last
            local total=0;for i=2,#points do total+=C.distance(points[i-1],points[i]) end
            if total>length then longest=points;length=total end
        end
        if not longest or length<=0 then return nil,'Native lane has no positive observed length' end
        local remaining=length*percent/100
        for i=2,#longest do
            local a,b=longest[i-1],longest[i];local segment=C.distance(a,b)
            if segment>0 and remaining<=segment then
                local t=remaining/segment
                return {a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t,a[3]+(b[3]-a[3])*t}
            end
            remaining-=segment
        end
        return table.clone(longest[#longest])
    end
    local function within(part,root)
        if not root then return false end
        local at=part
        for _=1,12 do if at==root then return true end;if not at then break end;at=at.Parent end
        return false
    end
    local function surface(hit,terrain,ground,hill,def,x,z)
        if not hit or not hit.Instance then return nil,'No observed terrain surface' end
        local at=hit.Instance;local reached=false
        for _=1,12 do
            if not at then break end
            if at.Name=='_donotplace' then return nil,'First surface is _donotplace' end
            if at==terrain then reached=true;break end
            at=at.Parent
        end
        if not reached then return nil,'First surface terrain ancestry incomplete' end
        local class=within(hit.Instance,ground) and 'ground' or within(hit.Instance,hill) and 'hill'
        if not class then return nil,'First surface is not loaded ground/hill' end
        if (class=='hill' and not def.hill_unit and not def.hybrid_placement) or (class=='ground' and def.hill_unit) then
            return nil,'First surface conflicts with loaded ground/hill rule'
        end
        local p=position(hit.Position)
        if not p or not hit.Normal or not C.finite(hit.Normal.Y) or hit.Normal.Y<=0 then return nil,'First surface position/normal invalid' end
        if math.abs(p[1]-x)>0.05 or math.abs(p[3]-z)>0.05 then return nil,'First surface ray changed candidate X/Z' end
        return p,class
    end
    -- Replicated bounds are inspected in place; no workspace clone is created.
    local function boundsParts(root)
        if not root then return {} end
        local stack={root};local parts={};local count=0
        while #stack>0 do
            local at=table.remove(stack);count+=1
            if count>128 then return nil,'Loaded bounds observation exceeds128 nodes' end
            if at:IsA('BasePart') then
                if #parts>=64 then return nil,'Loaded bounds observation exceeds64 parts' end
                if not position(at.Size) or not at.CFrame then return nil,'Loaded bounds geometry incomplete' end
                parts[#parts+1]=at
            else
                local list,why=children(at,128,'Loaded bounds nodes');if not list then return nil,why end
                for _,v in ipairs(list) do stack[#stack+1]=v end
            end
        end
        return parts
    end
    local function overlapsBounds(parts,pos,radius)
        -- A sphere enclosing the proposed query box is conservative for rotated bounds.
        local reach=math.sqrt(radius*radius*2+9)
        for _,part in ipairs(parts) do
            local localPos=part.CFrame:PointToObjectSpace(Vector3.new(pos[1],pos[2]+3,pos[3]))
            if not position(localPos) then return true end
            local half=part.Size
            if math.abs(localPos.X)<=half.X/2+reach and math.abs(localPos.Y)<=half.Y/2+reach
                and math.abs(localPos.Z)<=half.Z/2+reach then return true end
        end
        return false
    end
    function N:close() self.closed=true end
    function N:plan(s,definitions,cfg)
        if self.closed then return nil,'Native planner closed' end
        if self.planning then return nil,'Native geometry plan already in progress' end
        self.planning=true;cfg=cfg or {}
        local function compute()
            if s.inMatch~=true or s.stageVerified~=true or s.modeVerified~=true
                or not table.find({'Story','Dungeon','Infinite','Challenge','Raid','Legend','Portal'},s.mode)
                or s.unitsComplete~=true or s.rosterComplete~=true then return nil,'Native map/roster/tower observation incomplete or unsupported' end
            if s.externalControllerActive then return nil,'External controller active' end
            if type(s.roster)~='table' or #s.roster==0 or #s.roster>6 or type(s.units)~='table' or #s.units>24 then
                return nil,'Native planner supports1–6 observed slots and at most24 own towers'
            end
            local percent=cfg.autoDistance==nil and 50 or cfg.autoDistance
            local groundPercent=cfg.autoGround==nil and 60 or cfg.autoGround;local hillPercent=cfg.autoHill==nil and 80 or cfg.autoHill
            for _,v in ipairs({percent,groundPercent,hillPercent}) do if not C.finite(v) or v<0 or v>100 then return nil,'Native placement percentage invalid' end end
            local anchor,why=lanePoint(percent);if not anchor then return nil,why end
            local terrain=child(WS,'_terrain');local ground,hill=child(terrain,'ground'),child(terrain,'hill')
            if not terrain or (not ground and not hill) then return nil,'Loaded _terrain ground/hill unavailable' end
            local road,units=child(WS,'_road'),child(WS,'_UNITS')
            if not road or not units then return nil,'Actual _road/_UNITS geometry unavailable' end
            if not Vector3 or not CFrame or not RaycastParams or not OverlapParams or not Enum or not Enum.RaycastFilterType
                or not task or type(task.wait)~='function' then return nil,'Native ray/overlap/yield capabilities unavailable' end
            local rp=RaycastParams.new();rp.FilterType=Enum.RaycastFilterType.Include;rp.FilterDescendantsInstances={terrain}
            local op=OverlapParams.new();op.FilterType=Enum.RaycastFilterType.Include;op.FilterDescendantsInstances={road,units};op.MaxParts=64
            local nativeBounds=child(WS,'_bounds');if nativeBounds then op.FilterDescendantsInstances[#op.FilterDescendantsInstances+1]=nativeBounds end
            local bounds;bounds,why=boundsParts(child(RS,'_bounds'));if not bounds then return nil,why end
            local standing,reserved={},{}
